INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pal Pachinko', 'Your job is boring. Pal Pachinko isn''t. Park this idle game in the corner of your screen and watch your balls drop along with your productivity. It''s the most efficient way to waste your time. Why focus on one thing when you can fail at two? It''s small enough that your boss won''t notice (probably).' FROM games WHERE igdb_id = 390593 ON CONFLICT (game_id, language_code) DO NOTHING;
