INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ranchbound', 'Ranchbound is a western-themed real-time strategy and management game focused on running and expanding a ranch. Players manage cowboys and livestock, assign workers to tasks, transport cattle between locations, and make economic decisions to keep the ranch profitable and alive. The game combines strategic planning, light survival elements, and a stylized depiction of life in the Wild West.' FROM games WHERE igdb_id = 386596 ON CONFLICT (game_id, language_code) DO NOTHING;
