INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Odd One Out Christmas', 'Odd One Out Christmas is a simple, fun word puzzle quiz game with 9 different festive subjects that can be selected on the rounds screen (for example Christmas Music). Each subject has 6 puzzles and each puzzle is a different category within the overall theme - for instance Christmas Carols or Christmas Pop Hits. For each category there are 12 answers on the screen but one does not belong in the category and is the odd one out. Simply find the answer in each category that does not belong. There is no time limit and each subject can be played as many times as you need to reach a great score!' FROM games WHERE igdb_id = 390896 ON CONFLICT (game_id, language_code) DO NOTHING;
