INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TypeCaster', 'A once-shameless thief, cursed with a slow, agonizing death, must now embark on a perilous journey to the top of the legendary Tower of Trials. This 2.5D action RPG challenges you to master lightning-fast reflexes and precise typing to battle hordes of fearsome monsters guarding each floor. Harness powerful spells, uncover treasures, and push yourself to the limits in your battle against the unknowns. Will you rise to the challenge and break the curse, or will you become another victim?' FROM games WHERE igdb_id = 374215 ON CONFLICT (game_id, language_code) DO NOTHING;
