INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shine On, My Little Sun', 'When the Sun fell, darkness covered the world. In the snowy wasteland, the town of Svargo thrived under its faint light. But the Sun did not go out. The small Sun sleeps atop a grim lighthouse. What happens when the Sun awakens, seeking a few days of simple childhood?' FROM games WHERE igdb_id = 320147 ON CONFLICT (game_id, language_code) DO NOTHING;
