INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swarm Me', 'A minimalist horde survival arena where you can’t shoot back. You’re hunted by an endless swarm of drones - kite the horde, bait them into deadly traps, upgrade your defenses, and survive as long as you can. Every minute the swarm grows denser, faster, and deadlier.' FROM games WHERE igdb_id = 374722 ON CONFLICT (game_id, language_code) DO NOTHING;
