INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Driving Rogue', 'Arcade driving meets roguelike chaos - fast, intense, and ridiculously addictive. In Driving Rogue, every run is a new story: the city keeps changing, and you’ll need pure focus to push your score to the limit. After each race, hit the shop and craft your build for the longest streak possible.' FROM games WHERE igdb_id = 386893 ON CONFLICT (game_id, language_code) DO NOTHING;
