INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sloppy Forgeries', 'Sloppy Forgeries is a fast-paced, two-player local multiplayer painting game. Each player is given a mouse, a blank canvas, and a few simple paint tools. Each round, a famous painting from art history is revealed. Players race to copy the painting as quickly and accurately as possible.' FROM games WHERE igdb_id = 306740 ON CONFLICT (game_id, language_code) DO NOTHING;
